current.custom_css:
.m-header__menu .m-menu__item--parent .m-menu__link--main {
  font-size: 14px;
}
.m-custom-content-section .m-product-option--content div {
  width: 100%;
}
.m-custom-content-section select {
  border-radius: 0;
}
.m-section__heading {
  letter-spacing: 1.5px;
}

.m-product-card__title .m-product-card__name {
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 14px;
}
.m-custom-hero .m-hero__subtitle {
  font-size: 16px;
  letter-spacing: 1.5px;
}
.m-custom-hero .m-hero__title {
  letter-spacing: 6px;

  font-family: "Futura";
}

.m-richtext__subtitle,
.m-hero__subtitle {
  font-size: 16px;
  letter-spacing: 1.5px;
}
.m-custom-hero-1 .m-hero__title {
  letter-spacing: 4px;
}
.m-footer .m-footer--block-our_store .social-media-links {
  margin: 40px -25px 0;
}
.m-footer .m-footer--block-our_store .social-media-links a {
  padding: 0 15px;
}
.m-footer .m-footer--block-our_store .social-media-links svg path {
  color: #000;
}
.m-footer--block-newsletter {
  --color-border: 0,0,0;
  border-radius: 0;
}
.m-custom-image-with-text .m-richtext__subtitle {
  font-size: 12px;
  line-height: 16px;
}
.m-custom-content__block .m-product-title {
  text-transform: uppercase;
  font-size: 30px;
  line-height: 50px;
  letter-spacing: 1.5px;
}
.m-custom-content__block .main-product__block-vendor {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #000;
}
.m-custom-content__block .m-product-option--label {
  display: none;
}
.m-custom-hero-1 .m-hero__title {
  font-family: "Futura";
}

@media (min-width: 768px) {
  .m-custom-content-section
  .m-custom-content__block-image {
    flex: 1 1 0%;
  }
  .m-custom-content-section
  .m-custom-content__block-product_form {
    width: 40%;
    max-width: 550px;
  }
}
@media (min-width: 1024px) {
  .m-custom-image-with-text .m-content-box__heading h3 {
    font-size: 30px;
    line-height: 50px;
    letter-spacing: 1.5px;
  }
  .m-custom-hero-1 .m-hero__title {
    font-size: 70px;
  }
  .m-custom-hero .m-hero__title {
    margin-bottom: 40px;
  }
}

@media (min-width: 1536px) {
  .m-custom-hero .m-hero__title {
    font-size: 70px;
    line-height: 1.17;
  }
}
@media (min-width: 1661px) {
  .m-custom-hero .m-hero__title {
    font-size: 100px;
    line-height: 1.17;
  }
}
@media (max-width: 767px) {
  .m-custom-content__block .m-product-title {
    font-size: 24px;
  }
  .m-custom-content-section .m-custom-content__wrapper {
    flex-direction: column-reverse;
  }
  .m-custom-hero .m-hero__inner,
  .m-custom-hero-1 .m-hero__inner {
    justify-content: center;
  }
  .m-custom-hero .m-hero__inner .m-hero__content,
  .m-custom-hero-1 .m-hero__inner .m-hero__content {
    text-align: center;
  }
  .m-custom-hero
    .m-hero__inner
    .m-hero__content
    .m-hero__subtitle,
  .m-custom-hero-1
    .m-hero__inner
    .m-hero__content
    .m-hero__subtitle {
    font-size: 14px;
  }
  .m-custom-hero
    .m-hero__inner
    .m-hero__content
    .m-hero__title,
  .m-custom-hero-1
    .m-hero__inner
    .m-hero__content
    .m-hero__title {
    font-size: 36px;
    line-height: 42px;
  }
  .m-custom-image-with-text .m-content-box__heading h3 {
    font-size: 24px;
    line-height: 42px;
  }
}
